function validateAge(age) {
  if (typeof age !== "number" || age < 0) {
    throw new Error("Invalid age");
  }
  return "ok";
}

for (const input of [25, -5, "x"]) {
  try {
    console.log(validateAge(input));
  } catch (e) {
    console.log(e.message);
  }
}
